mapper.select:
select * from event_erp.survey s

  s.is_template = 0
  and s.event_id = #{eventId}

    and s.title like concat('%', #{keyword}, '%')


    and s.status = #{keyword}


    and s.is_anonymous = #{anon}


    and (s.title like concat('%', #{keyword}, '%')
         or s.description like concat('%', #{keyword}, '%'))


order by s.created_at desc
limit #{cri.pageStart}, #{cri.perPageNum}

select count(*)
from event_erp.survey s

  s.is_template = 0
  and s.event_id = #{eventId}

    and s.title like concat('%', #{keyword}, '%')


    and s.status = #{keyword}


    and s.is_anonymous = #{anon}


    and (s.title like concat('%', #{keyword}, '%')
         or s.description like concat('%', #{keyword}, '%'))

select count(distinct user_id)
from event_erp.survey_response
where survey_id = #{surveyId}

select count(distinct user_id)
from event_erp.survey_response
where survey_id = #{surveyId}
  and user_id = #{userId}

select * from event_erp.survey_question
where survey_id = #{surveyId}
order by question_id asc

select * from event_erp.survey_option
where question_id = #{questionId}
order by opt_value asc, option_id asc
